shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-text: #f2ede3;
    --navy-muted: #9eb0c2;
    --crimson: #8b261d;
    --font-serif-cn: 'Noto Serif SC', serif;
    --font-sans-cn: 'Noto Sans SC', sans-serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', serif;
    --font-serif-en: 'Lora', 'Noto Serif SC', serif;
    --font-sans-en: 'Inter', 'Noto Sans SC', sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  /* Language Switching Protocol */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif-en);
    line-height: 1.75;
    overflow-x: hidden;
  }

  :host([lang="zh-CN"]) .wsj-shadow-body {
    font-family: var(--font-serif-cn);
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line-strong);
    padding: 0.65rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .section-pill {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    border-left: 1px solid var(--line-strong);
    padding-left: 0.75rem;
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
  }

  .lang-btn {
    appearance: none;
    background: transparent;
    border: none;
    padding: 0.32rem 0.75rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .article-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  /* Hero Header */
  .hero-header {
    border-bottom: 2px solid var(--ink);
    padding-bottom: 2rem;
    margin-bottom: 2.5rem;
  }

  .kicker-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-bottom: 1rem;
    font-family: var(--font-mono);
    font-size: 0.78rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .headline {
    font-family: var(--font-display);
    font-weight: 800;
    color: var(--ink);
    font-size: clamp(2rem, 4.2vw, 3.35rem);
    line-height: 1.18;
    letter-spacing: -0.015em;
    margin-bottom: 1.25rem;
    max-width: 24ch;
  }

  :host([lang="zh-CN"]) .headline {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    line-height: 1.28;
    letter-spacing: 0.01em;
    max-width: 28ch;
  }

  .hero-subgrid {
    display: grid;
    grid-template-columns: 1fr 340px;
    gap: 2rem;
    align-items: end;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
  }

  .editorial-standfirst {
    font-size: 1.12rem;
    line-height: 1.65;
    color: var(--muted);
    font-family: var(--font-serif-en);
  }

  :host([lang="zh-CN"]) .editorial-standfirst {
    font-family: var(--font-serif-cn);
  }

  .byline-box {
    font-family: var(--font-sans-en);
    font-size: 0.82rem;
    color: var(--muted);
    border-left: 2px solid var(--accent);
    padding-left: 1rem;
    line-height: 1.5;
  }

  .byline-authors {
    font-weight: 600;
    color: var(--ink);
    margin-bottom: 0.2rem;
  }

  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  /* Political Dossier Strip (Key Numbers / Context) */
  .dossier-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-bottom: 3rem;
  }

  .dossier-cell {
    background: var(--paper-card);
    padding: 1.15rem 1.25rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .dossier-tag {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 0.35rem;
  }

  .dossier-num {
    font-family: var(--font-display);
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }

  .dossier-desc {
    font-family: var(--font-sans-en);
    font-size: 0.8rem;
    line-height: 1.45;
    color: var(--muted);
  }

  :host([lang="zh-CN"]) .dossier-desc {
    font-family: var(--font-sans-cn);
  }

  /* Editorial Two-Column Asymmetric Layout */
  .editorial-stage {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(280px, 380px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  .narrative-col {
    min-width: 0;
  }

  .sidebar-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    line-height: 1.85;
    color: var(--body);
    margin-bottom: 1.5rem;
  }

  :host([lang="zh-CN"]) .prose-p {
    font-size: 1.12rem;
    line-height: 1.92;
    letter-spacing: 0.015em;
  }

  /* Lead paragraph styling (NO ::first-letter on Chinese) */
  .prose-lead {
    font-size: 1.24rem;
    line-height: 1.78;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.2rem;
    margin-bottom: 1.85rem;
  }

  :host([lang="zh-CN"]) .prose-lead {
    font-size: 1.2rem;
    line-height: 1.88;
  }

  /* Inline Highlight */
  mark.ed-hl {
    background: var(--accent-soft);
    color: inherit;
    padding: 0.06em 0.24em;
    border-bottom: 1.5px solid var(--accent);
    border-radius: 2px;
  }

  /* Chapter / Section Dividers within Narrative */
  .chapter-divider {
    margin: 2.6rem 0 1.6rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--accent);
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }

  .chapter-title {
    font-family: var(--font-sans-en);
    font-size: 0.95rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--ink);
  }

  :host([lang="zh-CN"]) .chapter-title {
    font-family: var(--font-sans-cn);
    font-size: 1.02rem;
  }

  /* Official No-Comment Stamp Box (for p5) */
  .official-response-bar {
    background: var(--paper-card);
    border-top: 1px solid var(--line-strong);
    border-bottom: 1px solid var(--line-strong);
    padding: 0.95rem 1.25rem;
    margin: 1.75rem 0;
    display: flex;
    align-items: center;
    gap: 0.85rem;
  }

  .official-badge {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--paper);
    background: var(--ink);
    padding: 0.2rem 0.5rem;
    flex-shrink: 0;
  }

  .official-response-bar .prose-p {
    margin-bottom: 0;
    font-family: var(--font-sans-en);
    font-size: 0.95rem;
    color: var(--muted);
    font-weight: 500;
  }

  :host([lang="zh-CN"]) .official-response-bar .prose-p {
    font-family: var(--font-sans-cn);
  }

  /* Derived Pull Quote Cards in Sidebar Rail */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 1.5rem 1.4rem;
    position: relative;
  }

  .pull-quote-kicker {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.65rem;
    display: block;
  }

  .pull-quote .quote-text {
    font-family: var(--font-display);
    font-size: 1.22rem;
    line-height: 1.45;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.85rem;
  }

  :host([lang="zh-CN"]) .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.15rem;
    line-height: 1.65;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Memoir Dossier Card (Navy Theme for "107 Days") */
  .memoir-box {
    background: var(--navy-bg);
    color: var(--navy-text);
    padding: 2rem;
    border-radius: 2px;
    margin: 2rem 0;
    border-left: 4px solid var(--accent);
  }

  .memoir-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
    padding-bottom: 0.85rem;
    margin-bottom: 1.25rem;
    flex-wrap: wrap;
    gap: 0.5rem;
  }

  .memoir-title {
    font-family: var(--font-mono);
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #e89958;
  }

  .memoir-sub {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--navy-muted);
  }

  .memoir-box .prose-p {
    color: var(--navy-text);
    font-size: 1.06rem;
    line-height: 1.82;
  }

  .memoir-box .prose-p:last-child {
    margin-bottom: 0;
  }

  .memoir-box mark.ed-hl {
    background: rgba(232, 153, 88, 0.22);
    border-bottom-color: #e89958;
    color: #fff;
  }

  /* Bespoke SVG Diagram Card */
  .diagram-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
  }

  .diagram-kicker {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 0.25rem;
  }

  .diagram-title {
    font-family: var(--font-display);
    font-size: 1.12rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }

  :host([lang="zh-CN"]) .diagram-title {
    font-family: var(--font-serif-cn);
  }

  .diagram-subtitle {
    font-family: var(--font-sans-en);
    font-size: 0.8rem;
    color: var(--muted);
    line-height: 1.45;
    margin-bottom: 1rem;
  }

  :host([lang="zh-CN"]) .diagram-subtitle {
    font-family: var(--font-sans-cn);
  }

  .svg-wrap {
    width: 100%;
    overflow: hidden;
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 0.5rem;
  }

  /* Career & Campaign Trail Tracker Card */
  .trail-card {
    background: var(--paper);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
  }

  .trail-list {
    list-style: none;
    margin-top: 0.85rem;
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }

  .trail-item {
    border-left: 2px solid var(--accent);
    padding-left: 0.85rem;
  }

  .trail-loc {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--ink);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  .trail-detail {
    font-family: var(--font-sans-en);
    font-size: 0.82rem;
    color: var(--muted);
    line-height: 1.45;
    margin-top: 0.15rem;
  }

  :host([lang="zh-CN"]) .trail-detail {
    font-family: var(--font-sans-cn);
  }

  /* Closing Verdict Quote Split (p12.s2) */
  .closing-coda {
    margin-top: 2rem;
    padding: 1.5rem 1.75rem;
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
  }

  .closing-coda-label {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--muted);
    margin-bottom: 0.45rem;
  }

  .closing-coda blockquote {
    font-family: var(--font-display);
    font-size: 1.4rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.35;
  }

  :host([lang="zh-CN"]) .closing-coda blockquote {
    font-family: var(--font-serif-cn);
    font-size: 1.3rem;
  }

  /* Footer */
  .ed-footer {
    margin-top: 4rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 960px) {
    .hero-subgrid {
      grid-template-columns: 1fr;
      gap: 1.25rem;
    }
    .dossier-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .editorial-stage {
      grid-template-columns: 1fr;
      gap: 2.25rem;
    }
  }

  @media (max-width: 560px) {
    .masthead {
      padding: 0.55rem 1rem;
    }
    .article-shell {
      padding: 1.5rem 1rem 3.5rem;
    }
    .dossier-strip {
      grid-template-columns: 1fr;
    }
    .memoir-box {
      padding: 1.35rem 1.15rem;
    }
    .prose-lead {
      font-size: 1.12rem;
      padding-left: 0.9rem;
    }
  }
